def _validate_statement(node, path):
    _require_dict(node, path, "statement")
    kind = node.get("kind")
    if not isinstance(kind, str):
        _fail(path, "statement node missing a string 'kind' field")
    allowed = _STATEMENT_KEYS.get(kind)
    if allowed is None:
        _fail(path.attr("kind"), f"unknown statement kind {kind!r}")
    _check_keys(node, allowed, path)

    if kind == "var_decl":
        name = _require_field(node, "name", path)
        if not isinstance(name, str) or not name:
            _fail(path.attr("name"),
                  "variable name must be a non-empty string")
        _check_type_name(_require_field(node, "type", path),
                         path.attr("type"), allow_void=False)
        if "init" in node:
            _validate_expr(node["init"], path.attr("init"))
    elif kind == "assign":
        target = _require_field(node, "target", path)
        if not isinstance(target, str) or not target:
            _fail(path.attr("target"),
                  "assignment target must be a non-empty name")
        _validate_expr(_require_field(node, "value", path),
                       path.attr("value"))
    elif kind == "if":
        _validate_expr(_require_field(node, "cond", path), path.attr("cond"))
        _validate_statement_list(_require_field(node, "then", path),
                                 path.attr("then"))
        if "else" in node:
            _validate_statement_list(node["else"], path.attr("else"))
    elif kind == "while":
        _validate_expr(_require_field(node, "cond", path), path.attr("cond"))
        _validate_statement_list(_require_field(node, "body", path),
                                 path.attr("body"))
    elif kind == "return":
        if "value" in node and node["value"] is not None:
            _validate_expr(node["value"], path.attr("value"))
    elif kind == "block":
        _validate_statement_list(_require_field(node, "body", path),
                                 path.attr("body"))


def _validate_expr(node, path):
    _require_dict(node, path, "expression")
    kind = node.get("kind")
    if not isinstance(kind, str):
        _fail(path, "expression node missing a string 'kind' field")

    if kind == "int":
        _check_keys(node, {"kind", "value"}, path)
        value = _require_field(node, "value", path)
        if not _is_int(value):
            _fail(path.attr("value"),
                  f"integer literal must be an int, got {type(value).__name__}")
    elif kind == "bool":
        _check_keys(node, {"kind", "value"}, path)
        value = _require_field(node, "value", path)
        if not isinstance(value, bool):
            _fail(path.attr("value"),
                  f"boolean literal must be a bool, got {type(value).__name__}")
    elif kind == "var":
        _check_keys(node, {"kind", "name"}, path)
        name = _require_field(node, "name", path)
        if not isinstance(name, str) or not name:
            _fail(path.attr("name"), "variable name must be a non-empty string")
    elif kind == "binary":
        _check_keys(node, {"kind", "op", "left", "right"}, path)
        op = _require_field(node, "op", path)
        if not isinstance(op, str) or op not in BINARY_OPS:
            _fail(path.attr("op"), f"unknown binary operator {op!r}")
        _validate_expr(_require_field(node, "left", path), path.attr("left"))
        _validate_expr(_require_field(node, "right", path), path.attr("right"))
    elif kind == "call":
        _check_keys(node, {"kind", "name", "args"}, path)
        name = _require_field(node, "name", path)
        if not isinstance(name, str) or not name:
            _fail(path.attr("name"), "callee name must be a non-empty string")
        args = _require_field(node, "args", path)
        if not isinstance(args, list):
            _fail(path.attr("args"),
                  f"expected an argument list, got {type(args).__name__}")
        for i, arg in enumerate(args):
            _validate_expr(arg, path.attr("args").index(i))
    else:
        _fail(path.attr("kind"), f"unknown expression kind {kind!r}")

"""Deterministic plain-text rendering of the non-SSA IR.

The text of an identical AST is byte-for-byte stable across processes:
blocks, temps and slots are printed in their allocated numeric order and
no object addresses or set/dict iteration ever surfaces.
"""

from .ir import Module


def _literal(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _format_instruction(instr):
    if instr.op == "const":
        return f"{instr.dest.name}: {instr.dest.type} = const {_literal(instr.value)}"
    if instr.op == "load":
        return (f"{instr.dest.name}: {instr.dest.type} = load "
                f"{instr.slot.label}")
    if instr.op == "store":
        return f"store {instr.slot.label} {instr.operands[0].name}"
    if instr.op == "call":
        args = ", ".join(f"{op.name}: {op.type}" for op in instr.operands)
        return (f"{instr.dest.name}: {instr.dest.type} = call "
                f"@{instr.callee}({args})")
    # binary arithmetic / comparison ops
    left, right = instr.operands
    return (f"{instr.dest.name}: {instr.dest.type} = {instr.op} "
            f"{left.name} {right.name}")


def _format_terminator(term):
    if term.op == "return":
        if term.value is None:
            return "return"
        return f"return {term.value.name}: {term.value.type}"
    if term.op == "br":
        return f"br {term.targets[0].label}"
    # conditional branch: true target first, false target second
    return (f"cbr {term.condition.name} "
            f"{term.targets[0].label} {term.targets[1].label}")


def render_function(function):
    lines = []
    params = ", ".join(f"{p.name}: {p.type}" for p in function.params)
    lines.append(f"func @{function.name}({params}) -> {function.return_type} {{")

    for slot in function.slots:
        lines.append(f"  slot {slot.label}: {slot.type} ; {slot.name}")

    for block in function.blocks:
        lines.append(f"{block.label}:")
        for instr in block.instructions:
            lines.append(f"  {_format_instruction(instr)}")
        if block.terminator is not None:
            lines.append(f"  {_format_terminator(block.terminator)}")
    lines.append("}")
    return "\n".join(lines)


def render_module(module: Module) -> str:
    """Render a :class:`~compiler_ir.ir.Module` as deterministic text."""
    return "\n\n".join(render_function(fn) for fn in module.functions) + "\n"

